/* 工作记录交互演示：只存页面内存，不使用模型或业务接口。 */
let workNotes=[], noteSequence=0, noteQuery='', noteMonth=false;
function resetNotes(){workNotes=[];noteSequence=0;noteQuery='';noteMonth=false;}
function noteComposer(){return `<section class="card"><div class="cardhead row between wrap"><div><h2>记一句今天的工作</h2><small>自己办，告诉工作台一声就好。</small></div><button class="text" data-nav="notes">查看工作记录 →</button></div><form id="note-form" class="cardbody"><label class="field" for="note-text">做了什么，直接说<input id="note-text" name="text" maxlength="2000" required placeholder="例如：今天把部门会议材料整理好，发给办公室了。"></label><details class="history"><summary>补充发生日期（可不填）</summary><label class="field">发生日期<input type="date" name="date" max="2026-10-21"></label></details><div class="row between wrap" style="margin-top:14px"><small>演示仅保存原话，不自动判断完成、解析日期或关联项目。</small><button class="primary" type="submit">记下来</button></div><p class="error" id="note-error" role="alert"></p></form></section>`;}
function notesPage(){const active=workNotes.filter(n=>!n.withdrawn);const filtered=active.filter(n=>(!noteQuery||n.text.includes(noteQuery))&&(!noteMonth||n.date?.startsWith('2026-10')));const unknown=active.filter(n=>!n.date&&(!noteQuery||n.text.includes(noteQuery))).length;return `<div class="pagehead"><div class="eyebrow">工作记忆</div><h1>你做过的事，留得下来。</h1><p>工作记录按原话留存，不创建任务，不要求办结。</p></div>${noteComposer()}<section class="card"><div class="cardhead"><h2>查找工作记录</h2><form id="note-search" class="row wrap" style="margin-top:12px"><label style="flex:1">关键词<input name="query" value="${esc(noteQuery)}" placeholder="例如：会议材料"></label><button type="submit">查找记录</button><button type="button" data-note-action="month">${noteMonth?'查看全部时间':'查看本月记录'}</button></form></div><div class="cardbody"><p class="muted">${noteMonth?'2026年10月 · 按填写的发生日期':'全部时间'} · 找到${filtered.length}条原话记录，不能据此认定完成事项数量。</p>${noteMonth&&unknown?`<p class="note warn" style="margin-top:12px">另有${unknown}条未填写发生日期，未计入本月结果。可查看全部时间后补充。</p>`:''}</div>${filtered.length?filtered.map(n=>`<article class="record"><div class="row between wrap"><span class="tag neutral">用户陈述 · ${n.date?esc(n.date):'发生日期未说明'}</span><small>记录 #${n.id} · v${n.history.length+1}</small></div><p class="description">${esc(n.text)}</p><div class="row wrap"><button class="text" data-note-action="edit" data-note-id="${n.id}">更正记录 #${n.id}</button><button class="text" data-note-action="withdraw" data-note-id="${n.id}">撤回记录 #${n.id}</button>${n.history.length?`<details class="history"><summary>查看更正前原话</summary>${n.history.map(h=>`<p>${esc(h.text)} · ${esc(h.date||'日期未说明')}</p>`).join('')}</details>`:''}</div><small>录入于演示日期2026-10-21；这是告知内容，不是外部凭证。</small></article>`).join(''):'<div class="empty"><h3>还没有符合条件的记录</h3><p class="muted">可以在上方记一句，或调整时间与关键词。没有记录不等于没有开展工作。</p></div>'}</section><p class="muted">原型中的记录刷新即重置；正式方案要求落库后跨会话保留，并在相关问答和总结中引用记录来源。</p>`;}
document.addEventListener('submit',e=>{
 if(e.target.id==='note-form'){e.preventDefault();const fd=new FormData(e.target),text=String(fd.get('text')||'').trim(),date=String(fd.get('date')||'');if(!text){document.querySelector('#note-error').textContent='请说一下做了什么，不能只输入空格。';return}if(date>'2026-10-21'){document.querySelector('#note-error').textContent='实际发生日期不能在演示时点之后。';return}workNotes.unshift({id:++noteSequence,text,date:date||null,history:[],withdrawn:false});noteQuery='';noteMonth=false;go('notes');toast('已记录这句原话，可更正或撤回。没有创建待办。');}
 if(e.target.id==='note-search'){e.preventDefault();noteQuery=String(new FormData(e.target).get('query')||'').trim();render();}
});
document.addEventListener('click',e=>{const b=e.target.closest('[data-note-action]');if(!b)return;const n=workNotes.find(n=>n.id===Number(b.dataset.noteId));if(b.dataset.noteAction==='month'){noteMonth=!noteMonth;render();return}if(!n)return;
 if(b.dataset.noteAction==='withdraw'){n.withdrawn=true;render();toast('已撤回，不再用于回顾或总结。本次演示刷新即清空。');return}
 if(b.dataset.noteAction==='edit'){showDialog(`更正工作记录 #${n.id}`,`<label class="field">原话内容<textarea name="text" required maxlength="2000">${esc(n.text)}</textarea></label><label class="field">发生日期（可空）<input type="date" name="date" max="2026-10-21" value="${esc(n.date||'')}"></label><p class="muted">保留更正前版本；回顾时使用更正后的内容。</p>`,'<button class="primary" type="submit">保存更正</button>');document.querySelector('#dialog-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),text=String(fd.get('text')||'').trim(),date=String(fd.get('date')||'');if(!text)return fail('原话不能只输入空格。');if(date>'2026-10-21')return fail('实际发生日期不能在演示时点之后。');if(text!==n.text||(date||null)!==n.date){n.history.push({text:n.text,date:n.date});n.text=text;n.date=date||null}closeDialog();render();toast('已更正，旧版本仍可查看。')}}
});
